public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
        Set<Integer> startSet = new HashSet<>();
        Set<Integer> endSet = new HashSet<>();
        for (int[] path : paths) {
            startSet.add(path[0]);
            endSet.add(path[1]);
        }
        return startSet.contains(start[0]) && endSet.contains(end[0]) ? "can be travelled" : "cannot be travelled";
    }

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[] visited = new boolean[n * n];
    int startIdx = start[0] * n + start[1];
    int endIdx = end[0] * n + end[1];
    return canTravelMazeHelper(startIdx, endIdx, paths, visited) ? "can be travelled" : "cannot be travelled";
}

private static boolean canTravelMazeHelper(int current, int end, int[][] paths, boolean[] visited) {
    if (current == end) {
        return true;
    }
    visited[current] = true;
    for (int i = 0; i < paths.length; i++) {
        int[] path = paths[i];
        int from = path[0];
        int to = path[1];
        if (!visited[to] && (from == current)) {
            if (canTravelMazeHelper(to, end, paths, visited)) {
                return true;
            }
        }
    }
    return false;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[] visited = new boolean[n];
    List<List<Integer>> adjList = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        adjList.add(new ArrayList<>());
    }
    for (int[] path : paths) {
        adjList.get(path[0]).add(path[1]);
        adjList.get(path[1]).add(path[0]);
    }
    if (isReachable(adjList, start[0], end[0], visited)) {
        return "can be travelled";
    } else {
        return "cannot be travelled";
    }
}

private static boolean isReachable(List<List<Integer>> adjList, int start, int end, boolean[] visited) {
    if (start == end) {
        return true;
    }
    visited[start] = true;
    for (int neighbor : adjList.get(start)) {
        if (!visited[neighbor] && isReachable(adjList, neighbor, end, visited)) {
            return true;
        }
    }
    return false;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[] visited = new boolean[n];
    return dfs(visited, start[0], end[0], paths) ? "can be travelled" : "cannot be travelled";
}

private static boolean dfs(boolean[] visited, int current, int end, int[][] paths) {
    if (current == end) {
        return true;
    }
    visited[current] = true;
    for (int next : getAdjacent(current, paths)) {
        if (!visited[next] && dfs(visited, next, end, paths)) {
            return true;
        }
    }
    return false;
}

private static int[] getAdjacent(int current, int[][] paths) {
    int[] adj = new int[0];
    for (int[] path : paths) {
        if (path[0] == current) {
            if (adj.length == 0) {
                adj = new int[]{path[1]};
            } else {
                int[] temp = new int[adj.length + 1];
                System.arraycopy(adj, 0, temp, 0, adj.length);
                temp[adj.length] = path[1];
                adj = temp;
            }
        } else if (path[1] == current) {
            if (adj.length == 0) {
                adj = new int[]{path[0]};
            } else {
                int[] temp = new int[adj.length + 1];
                System.arraycopy(adj, 0, temp, 0, adj.length);
                temp[adj.length] = path[0];
                adj = temp;
            }
        }
    }
    return adj;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    Set<Integer> startNode = new HashSet<>();
    startNode.add(start[0] * n + start[1]);
    Set<Integer> endNode = new HashSet<>();
    endNode.add(end[0] * n + end[1]);

    Set<Integer> visited = new HashSet<>();
    Queue<Integer> queue = new LinkedList<>();
    queue.addAll(startNode);
    visited.addAll(startNode);

    while (!queue.isEmpty()) {
        Integer current = queue.poll();

        for (int[] path : paths) {
            int x = path[0];
            int y = path[1];
            int neighbor = x * n + y;

            if (!visited.contains(neighbor)) {
                visited.add(neighbor);
                queue.add(neighbor);

                if (endNode.contains(neighbor)) {
                    return "can be travelled";
                }
            }
        }
    }

    return "cannot be travelled";
}

public static String appx(String word1, String word2) {
    String commonLetters = "";
    for (char c1 : word1.toCharArray()) {
        if (word2.indexOf(c1) >= 0 && commonLetters.indexOf(c1) < 0) {
            commonLetters += c1;
        }
    }
    int numerator = commonLetters.length();
    int denominator = word1.length() + word2.length() - numerator;
    int gcd = gcd(numerator, denominator);
    return "appx(" + word1 + ", " + word2 + ") = " + (numerator / gcd) + "/" + (denominator / gcd);
}

private static int gcd(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

