public int minTime(int n, int[][] edges, boolean[] hasApple) {
    Map<Integer, List<Integer>> adj = new HashMap<>();
    for (int[] edge : edges) {
        adj.computeIfAbsent(edge[0], k -> new ArrayList<>()).add(edge[1]);
        adj.computeIfAbsent(edge[1], k -> new ArrayList<>()).add(edge[0]);
    }
    return dfs(0, -1, adj, hasApple) * 2;
}

private int dfs(int node, int parent, Map<Integer, List<Integer>> adj, boolean[] hasApple) {
    int time = 0;
    for (int neighbor : adj.get(node)) {
        if (neighbor == parent) continue;
        int childTime = dfs(neighbor, node, adj, hasApple);
        if (childTime > 0 || hasApple[neighbor]) {
            time += childTime + 2;
        }
    }
    return time;
}

