public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    for (int i = 1; i <= n / 2; i++) {
        if (sum * i % n == 0) {
            if (containsSum(nums, i, sum * i / n)) {
                return true;
            }
        }
    }
    return false;
}

private boolean containsSum(int[] nums, int k, int target) {
    boolean[] dp = new boolean[target + 1];
    dp[0] = true;
    for (int num : nums) {
        for (int j = target; j >= num; j--) {
            dp[j] = dp[j] || dp[j - num];
        }
    }
    return dp[target];
}

public boolean splitArraySameAverage(int[] A) {
    int n = A.length;
    int sum = 0;
    for (int a : A) sum += a;

    boolean[][] dp = new boolean[n + 1][sum + 1];
    dp[0][0] = true;

    for (int i = 1; i <= n; i++) {
        for (int j = sum; j >= A[i - 1]; j--) {
            for (int k = 0; k <= i; k++) {
                dp[k][j] = dp[k][j] || (k > 0 && dp[k - 1][j - A[i - 1]]);
            }
        }
    }

    for (int i = 1; i <= n / 2; i++) {
        if (dp[i][sum * i / n]) return true;
    }

    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    boolean[][] dp = new boolean[n + 1][sum + 1];
    dp[0][0] = true;
    for (int i = 0; i < n; i++) {
        for (int j = sum; j >= nums[i]; j--) {
            dp[i + 1][j] = dp[i][j] || dp[i][j - nums[i]];
        }
    }
    for (int s = 1; s <= sum; s++) {
        if (s * n == sum * (n - 1) || s == 0) continue;
        if (dp[n][s] && dp[n - 1][s * (n - 1) - sum]) return true;
    }
    return false;
}

