            Set<Integer> set = new HashSet<>();
            set.add(0);
            int sum = 0;
            for (int num : nums) {
                for (int j = set.size() - 1; j >= 0; j--) {
                    int s = set.toArray(new int[0])[j] + num;
                    if (s == totalSum * i / n) {
                        return true;
