public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    boolean[][] possible = new boolean[n + 1][sum + 1];
    possible[0][0] = true;

    for (int i = 1; i <= n; i++) {
        int num = nums[i - 1];
        for (int j = sum; j >= num; j--) {
            possible[i][j] = possible[i - 1][j] || possible[i - 1][j - num];
        }
        for (int j = 0; j < num; j++) {
            possible[i][j] = possible[i - 1][j];
        }
    }

    for (int i = 1; i < n; i++) {
        for (int j = 1; j <= sum; j++) {
            if (possible[i][j] && possible[n - i][sum - j] && i * (sum - j) == (n - i) * j) {
                return true;
            }
        }
    }

