            balance++;
            i++;
        } else {
            if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
                i += 2;
            } else {
                insertions++;
                i++;
            }
            if (balance > 0) {
                balance--;
            } else {
                insertions++;
            }
        }
    }
    insertions += balance * 2;
    return insertions;
}

