public int findMinFibonacciNumbers(int k) {
    List<Integer> fibs = new ArrayList<>();
    fibs.add(1);
    fibs.add(1);

    while (fibs.get(fibs.size() - 1) < k) {
        int n = fibs.size();
        fibs.add(fibs.get(n - 1) + fibs.get(n - 2));
    }

    int count = 0;
    for (int i = fibs.size() - 1; i >= 0; i--) {
        if (k >= fibs.get(i)) {
            k -= fibs.get(i);
            count++;
        }
        if (k == 0) {
            break;
        }
    }

    return count;
}

