private int maxUniqueSplitHelper(String s, Set<String> seen) {
    if (s.isEmpty()) {
        return 0;
    }
    int max = 0;
    for (int i = 1; i <= s.length(); i++) {
        String prefix = s.substring(0, i);
        if (!seen.contains(prefix)) {
            seen.add(prefix);
            max = Math.max(max, 1 + maxUniqueSplitHelper(s.substring(i), seen));
            seen.remove(prefix);
        }
    }
    return max;
}

