    int[] diagonal = new int[m + n + 1];
    int[] antiDiagonal = new int[m + n + 1];

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                // Update the counts for horizontal, vertical, diagonal, and anti-diagonal lines
                horizontal[j]++;
                vertical[i]++;
                diagonal[i + j]++;
                antiDiagonal[i - j + n]++;

                // Update the maximum length
                maxLength = Math.max(maxLength, horizontal[j]);
                maxLength = Math.max(maxLength, vertical[i]);
                maxLength = Math.max(maxLength, diagonal[i + j]);
                maxLength = Math.max(maxLength, antiDiagonal[i - j + n]);
            } else {
                // Reset the counts if the current cell is 0
                horizontal[j] = 0;
                vertical[i] = 0;
                diagonal[i + j] = 0;
                antiDiagonal[i - j + n] = 0;
            }
        }
    }

    return maxLength;
