public static int squarePermutations(int[] A) {
    int N = A.length;
    if (N == 0) return 1;
    return permute(A, 0, new boolean[N]);
}

private static int permute(int[] A, int start, boolean[] used) {
    if (start == A.length) return 1;
    int count = 0;
    for (int i = 0; i < A.length; i++) {
        if (used[i] || (start > 0 && !isPerfectSquare(A[start - 1] + A[i]))) continue;
        used[i] = true;
        count += permute(A, start + 1, used);
        used[i] = false;
    }
    return count;
}

private static boolean isPerfectSquare(int num) {
    int sqrt = (int) Math.sqrt(num);
    return sqrt * sqrt == num;
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    int[][] dp = new int[1 << n][n];
    dp[0][0] = 1;

    for (int mask = 1; mask < (1 << n); mask++) {
        for (int i = 0; i < n; i++) {
            if ((mask & (1 << i)) == 0) continue;
            for (int j = 0; j < i; j++) {
                if ((mask & (1 << j)) == 0) continue;
                int num = A[i] + A[j];
                if (isPerfectSquare(num)) {
                    dp[mask][i] += dp[mask ^ (1 << i)][j];
                }
            }
        }
    }

    int result = 0;
    for (int i = 0; i < n; i++) {
        result += dp[(1 << n) - 1][i];
    }

    return result;
}

private static boolean isPerfectSquare(int num) {
    int root = (int) Math.sqrt(num);
    return root * root == num;
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    int[] dp = new int[1 << n];
    dp[0] = 1;
    for (int i = 0; i < 1 << n; i++) {
        for (int j = 0; j < n; j++) {
            if ((i & (1 << j)) != 0) {
                int sum = 0;
                for (int k = 0; k < n; k++) {
                    if ((i & (1 << k)) != 0 && Math.abs(A[j] - A[k]) == 1) {
                        sum += A[k];
                        if (Integer.isPerfectSquare(sum)) {
                            dp[i] += dp[i ^ (1 << j)];
                        }
                    }
                }
            }
        }
    }
    return dp[(1 << n) - 1];
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    int[] count = new int[10001];
    for (int a : A) {
        count[a]++;
    }
    int[][] dp = new int[n][n];
    for (int i = 0; i < n; i++) {
        dp[i][i] = count[A[i]];
    }
    for (int len = 2; len <= n; len++) {
        for (int i = 0; i <= n - len; i++) {
            int j = i + len - 1;
            dp[i][j] = 0;
            for (int k = i; k < j; k++) {
                int sum = A[k] + A[k + 1];
                int perfectSquareRoot = (int) Math.sqrt(sum);
                if (perfectSquareRoot * perfectSquareRoot == sum) {
                    dp[i][j] += dp[i][k] * dp[k + 1][j] * count[A[k]];
                }
            }
        }
    }
    int result = 0;
    for (int i = 0; i < n; i++) {
        result += dp[0][i];
    }
    return result;
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;

    boolean[] visited = new boolean[n];
    int result = 0;
    backtrack(A, visited, 0, result);
    return result;
}

private static void backtrack(int[] A, boolean[] visited, int index, int[] result) {
    if (index == A.length - 1) {
        result[0]++;
        return;
    }

    for (int i = 0; i < A.length; i++) {
        if (visited[i]) continue;
        if (index == 0 || isPerfectSquare(A[index] + A[i])) {
            visited[i] = true;
            backtrack(A, visited, index + 1, result);
            visited[i] = false;
        }
    }
}

private static boolean isPerfectSquare(int num) {
    int sqrt = (int) Math.sqrt(num);
    return sqrt * sqrt == num;
}

