public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }

    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int r = 0, c = 0;

    for (int i = 0; i < m * n; i++) {
        result[i] = mat[r][c];
        if ((r + c) % 2 == 0) {
            if (c == n - 1) {
                r++;
            } else if (r == 0) {
                c++;
            } else {
                r--;
                c++;
            }
        } else {
            if (r == m - 1) {
                c++;
            } else if (c == 0) {
                r++;
            } else {
                r++;
                c--;
            }
        }
    }

    return result;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) return new int[0];
    int m = mat.length, n = mat[0].length;
    int[] result = new int[m * n];
    int row = 0, col = 0, d = 1; // d: 1 for up-right, -1 for down-left
    for (int i = 0; i < result.length; i++) {
        result[i] = mat[row][col];
        row -= d;
        col += d;
        if (row < 0) {
            row = 0;
            d = -d;
        } else if (col < 0) {
            col = 0;
            d = -d;
        } else if (row >= m) {
            row = m - 1;
            col += 2;
            d = -d;
        } else if (col >= n) {
            col = n - 1;
            row += 2;
            d = -d;
        }
    }
    return result;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int r = 0, c = 0;

    for (int i = 0; i < rows + cols - 1; i++) {
        if (i % 2 == 0) {
            // Upward diagonal
            while (r >= 0 && c < cols) {
                result[i] = mat[r][c];
                i++;
                r--;
                c++;
            }
            if (c == cols) {
                c--;
                r += 2;
            } else {
                r = 0;
            }
        } else {
            // Downward diagonal
            while (c >= 0 && r < rows) {
                result[i] = mat[r][c];
                i++;
                r++;
                c--;
            }
            if (r == rows) {
                r--;
                c += 2;
            } else {
                c = 0;
            }
        }
    }

    return result;
}

public static int[] diagonalOrder(int[][] mat) {
