    int m = mat.length, n = mat[0].length;
    int[] result = new int[m * n];
    int r = 0, c = 0, i = 0;

    while (r < m && c < n) {
        if ((r + c) % 2 == 0) {
            while (r >= 0 && c < n) result[i++] = mat[r--][c++];
            if (c == n) c = n - 1;
            r = r + 2;
        } else {
            while (c >= 0 && r < m) result[i++] = mat[r++][c--];
            if (r == m) r = m - 1;
            c = c + 2;
        }
    }

    return result;
}

