public static List<String> centerSymmetricNumbers(int n) {
    if (n == 0) return Arrays.asList();
    if (n == 1) return Arrays.asList("0", "1", "8");

    List<String> result = new ArrayList<>();
    helper(result, new char[n], 0, n - 1, "01869");

    return result;
}

private static void helper(List<String> result, char[] current, int left, int right, String options) {
    if (left > right) {
        result.add(String.copyValueOf(current));
        return;
    }

    for (char option : options.toCharArray()) {
        if (left == right && option == '0' && current.length != 1) continue;
        current[left] = option;
        current[right] = map(option);
        helper(result, current, left + 1, right - 1, options);
    }
}

private static char map(char c) {
    if (c == '6') return '9';
    if (c == '9') return '6';
    return c;
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n == 0) return result;
    if (n == 1) {
        result.add("0");
        result.add("1");
        result.add("8");
        return result;
    }

    List<String> half = centerSymmetricNumbers(n - 2);
    String mid = n % 2 == 0 ? "" : "018";
    for (String s : half) {
        for (char c : mid.toCharArray()) {
            result.add(c + s + c);
        }
    }

    return result;
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n == 0) {
        return result;
    }
    if (n == 1) {
        result.add("0");
        result.add("1");
        result.add("8");
        return result;
    }
    char[] symmetries = {'0', '1', '6', '8', '9'};
    char[] mid = {'0', '1', '8'};
    if (n % 2 == 1) {
        helper(result, new char[n], symmetries, mid, 0, n - 1, (n - 1) / 2);
    } else {
        helper(result, new char[n], symmetries, mid, 0, n - 1, n / 2 - 1);
    }
    return result;
}

private static void helper(List<String> result, char[] current, char[] symmetries, char[] mid, int left, int right, int midIndex) {
    if (left > right) {
        result.add(new String(current));
        return;
    }
    for (char s : symmetries) {
        if (left == right && s == '0') continue; // Avoid leading zeros
        current[left] = s;
        current[right] = getSymmetry(s);
        if (left < midIndex && current[left] == '6' || current[left] == '9') continue; // Avoid invalid middle digits
        helper(result, current, symmetries, mid, left + 1, right - 1, midIndex);
    }
}

private static char getSymmetry(char c) {
    switch (c) {
        case '6': return '9';
        case '9': return '6';
        default: return c;
    }
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    backtrack(result, new char[n], 0, n - 1);
    return result;
}

private static void backtrack(List<String> result, char[] chars, int left, int right) {
    char[] pairs = {'0', '1', '6', '8', '9'};
    if (left > right) {
        result.add(new String(chars));
        return;
    } else if (left == right) {
        for (char c : pairs) {
            if (c != '0') {
                chars[left] = c;
                result.add(new String(chars));
            }
        }
    } else {
        for (int i = 0; i < pairs.length; i++) {
            if (i > 1 && left == 0) continue; // Avoid leading zero for numbers longer than 1
            chars[left] = pairs[i];
            chars[right] = centerSymmetricPair(pairs[i]);
            backtrack(result, chars, left + 1, right - 1);
        }
    }
}

private static char centerSymmetricPair(char c) {
    if (c == '0') return '0';
    if (c == '1') return '1';
    if (c == '6') return '9';
    if (c == '8') return '8';
    return '6';
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    dfs(result, "", n, n);
    return result;
}

private static void dfs(List<String> result, String path, int left, int right) {
    if (left > right) {
        result.add(path);
        return;
    }
    if (left == right) {
        for (char c : new char[]{'0', '1', '8'}) {
            if (path.length() == 0 && c == '0') continue;
            result.add(path + c);
        }
    } else {
        for (char c : new char[]{'0', '1', '8', '6', '9'}) {
            if (left == 0 && c == '0') continue;
            dfs(result, path + c, left - 1, right + 1);
        }
    }
}

